  var SPLIT = /(?<=[.!?…])\s+/;
  D.forEach(function (p) {
    var a = key(p[0]).split(SPLIT), b = p[1].split(SPLIT);
    if (a.length > 1 && a.length === b.length) a.forEach(function (s, i) { if (dict[s] == null) dict[s] = b[i]; });
  });
