  function fromEs(f) {
    var k = String(f || "").replace(/'/g, "’"), m;
    if (FROM[k]) return FROM[k];
    if ((m = /^from the book of (\w+)$/.exec(k)) && BOOK[m[1]]) return "del libro " + BOOK[m[1]];
    if ((m = /^a story of (Saints? .+)$/.exec(k)) && SAINT[m[1]]) return "una historia de " + SAINT[m[1]];
    if ((m = /^a sakhi of (Guru [\w ]+|Bhai \w+)$/.exec(k))) return "un sakhi de " + m[1];
    if ((m = /^a traditional story of (.+)$/.exec(k))) return "una historia tradicional de " + m[1].replace(/ and Emperor /, " y el emperador ");
    if ((m = /^Sikh history and tradition, (.+)$/.exec(k))) return "historia y tradición sij, " + m[1];
    if ((m = /^an old story (?:about|of) (.+)$/.exec(k))) return "una historia antigua de " + m[1].replace(/^the /, "los ").replace("Pythagoreans", "pitagóricos").replace(/ and /, " y ");
    if (/^[A-Z][\w ]*$/.test(k) || /^[a-z]+ [a-z]+$/.test(k) && !/^(from|a|an|the) /.test(k) || /^[A-Z][\w]+, \d{4}$/.test(k)) return k; // a festival or a name ("Ugadi", "griha pravesh", "Vaisakhi, 1699")
    return null;
  }
